def download(store, name):
    """Handle GET /files/<name>: returns (status, body)."""
    try:
        return 200, store.read(name)
    except PermissionError:
        return 403, b"forbidden"
    except (FileNotFoundError, IsADirectoryError):
        return 404, b"not found"

