import os
import unittest

from server import download
from site_fixture import make_site
from storage import FileStore


class Regression(unittest.TestCase):
    def setUp(self):
        self.base, uploads = make_site()
        self.store = FileStore(uploads)

    def test_an_absolute_path_cannot_leave_either(self):
        secret = os.path.join(self.base, "config", "secrets.env")
        self.assertEqual(download(self.store, secret)[0], 403)

    def test_normal_files_still_download(self):
        self.assertEqual(download(self.store, "cat.png"), (200, b"meow"))

    def test_a_name_with_two_dots_in_it_is_fine(self):
        self.assertEqual(download(self.store, "q3..final.csv"), (200, b"revenue"))

    def test_a_missing_file_is_404(self):
        self.assertEqual(download(self.store, "nope.txt")[0], 404)

